function handleMoviesClick() {
    console.log('handleMoviesClick - For backward compatibility with hard-coded buttons');
    
    /* Find the movies button generated by the API */
    const movieButton = document.querySelector('button[id="70"]'); // Movies ID from API
    
    /* If found, simulate a click on it to use the API-driven implementation */
    if (movieButton) {
        movieButton.click();
    } else {
        /* Fallback for cases where the API button isn't found */
        previous_page = current_page;
        current_page = 'movies';
        
        /* Same sequence as in API click handler */
        enableBackKeyForwarding();
        setMoviesKeys();
        openMovies('Activate');
    }
}

function handleRadioClick() {
    console.log('Opening Radio...');
    
    // Hide default view
    //document.querySelector('.default-view').style.display = 'none';
    
    // Hide entertainment view
    document.querySelector('#entertainment_menu').style.display = 'none';
    
    // Keep sidebar visible
    const sidebar = document.querySelector('.sidebar');
    if (sidebar) {
        sidebar.style.display = 'none';
    }
    
    // Show radio view
    const radioView = document.querySelector('.radio-view');
    if (radioView) {
        radioView.style.display = 'flex';
        //radioView.style.marginLeft = '15%'; // Align with sidebar
    }

    // First make sure to remove any radio channels from the TV app
    if (typeof removeRadioChannelsFromTV === 'function') {
        removeRadioChannelsFromTV();
    }

    // Initialize radio channels
    openRadio();
}

