function handleEntertainmentClick() {
    console.log('Opening Entertainment...');

    //setting previous and current page
    previous_page = current_page;
    current_page = "entertainment_menu";

    document.getElementById(previous_page).style.display = 'none';
    document.getElementById(current_page).style.display = 'flex';

    //document.getElementById("tv_button").focus();

}


// Add entertainment casting handler
function handleCastingClick() {
    console.log('handleCastingClick - For backward compatibility with hard-coded buttons');
    
    /* Find the casting button generated by the API */
    const castingButton = document.querySelector('button[id="98"]'); // Casting ID from API
    
    /* If found, simulate a click on it to use the API-driven implementation */
    if (castingButton) {
        castingButton.click();
    } else {
        /* Fallback for cases where the API button isn't found */
        previous_page = current_page;
        current_page = 'casting';
        
        /* Same sequence as in API click handler */
        enableBackKeyForwarding();
        SelectCast('Activate');
    }
}

